#include <map>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<vector<long long>> g(n, vector<long long>(n));
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            cin >> g[i][j];
        }
    }

    map<vector<long long>, long long> rowsCount;
    for (int i = 0; i < n; i++) rowsCount[g[i]]++;
    long long total = 0;
    for (int j = 0; j < n; j++) {
        vector<long long> col(n);
        for (int i = 0; i < n; i++) col[i] = g[i][j];
        auto it = rowsCount.find(col);
        if (it != rowsCount.end()) total += it->second;
    }
    cout << total << "\n";

    return 0;
}

